import{_ as l,l as i,o as e,c as n,v as o,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"2D RoPE","description":"","frontmatter":{"title":"2D RoPE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/2d-rope.md","filePath":"llm/2d-rope.md","lastUpdated":1789023840000}'),h={name:"llm/2d-rope.md"};function _(c,a,m,P,R,D){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="_2d-rope" tabindex="-1">2D RoPE <a class="header-anchor" href="#_2d-rope" aria-label="Permalink to &quot;2D RoPE&quot;">​</a></h1><div class="epigraph"><p>一维 RoPE 把序列当下标。图像的邻居在二维格子上。把旋转拆到高与宽，相对位置才回到上下左右。</p><footer>—— Su 等 RoFormer 的旋转位置；VLM 中的二维 / 多轴推广</footer></div><p><a href="/llm/native-resolution-vit">上一课</a>需要二维位置。主干文本 RoPE 把位置写成旋转。本课写 2D RoPE：对 patch 坐标 \\((x,y)\\) 分别旋转一部分维度。缺口是不要把图像当一维 raster 编号完事。后课视觉指令数据默认位置编码已经能表达格子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可学习一维位置嵌入难外推分辨率。一维 RoPE 外推的是长度，不是高宽。把 patch 按行扫描编号，竖直邻居在序列上相距一行宽度，旋转角与真实空间距离不成比例。2D RoPE 把通道分成两组（或更多），一组旋转 \\(x\\)，一组旋转 \\(y\\)，注意力的相对相位由 \\(\\Delta x,\\Delta y\\) 决定。Qwen2-VL 的 M-RoPE 再把时间轴算进去，视频与图共用多轴。</p><p>分辨率变化时，坐标如何归一（像素、patch 格、还是 \\([0,1]\\)）是协议，写错会让高低分辨率图的「同一相对结构」对不上。</p><p><span class="marginnote">文本 token 仍用一维 RoPE。多模态序列里，视觉段用二维，文本段用一维，轴要对齐到同一旋转实现，避免两套尺度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对视觉 token 赋 \\((x,y)\\)（及视频 \\(t\\)），按轴应用 RoPE。训练应含多种分辨率，否则外推仍失败。与绝对 2D 嵌入可比：RoPE 利于相对几何，绝对嵌入利于「这是画布角落」的绝对先验。产品常用 RoPE。评测：把图平移/缩放后问相对位置，看是否保持。</p>',9)),(e(),s(E,null,{default:t(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20XY%5B%22patch%20%E5%9D%90%E6%A0%87%20x%2Cy%22%5D%20--%3E%20RX%5B%22%E9%83%A8%E5%88%86%E7%BB%B4%E6%97%8B%E8%BD%AC%20x%22%5D%0A%20%20XY%20--%3E%20RY%5B%22%E9%83%A8%E5%88%86%E7%BB%B4%E6%97%8B%E8%BD%AC%20y%22%5D%0A%20%20RX%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20RY%20--%3E%20ATT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RoPE 把点积变成带相对位置相位的形式。二维推广希望 \\(\\Delta x\\) 与 \\(\\Delta y\\) 可分地进入相位，于是「左边那个」在不同分辨率下仍对应相似的相对旋转。若把 \\(x,y\\) 编码进同一组维而不分轴，相位会耦合，竖向与横向相对关系缠在一起。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2D RoPE 不增加 OCR 分辨率——那是切块 \\(P\\) 与 \\(N\\)。它只让已有格子的相对结构可学。下一课：格子有了，还要指令数据才会对齐到语言动作。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2D RoPE 按高宽分轴旋转，修复 raster 一维编号的空间扭曲。</li><li>坐标归一与多分辨率训练属于协议。</li><li>文本一维与视觉二维要在同一实现里对齐尺度。</li><li>出处：Su 等 RoFormer；Qwen2-VL 等多轴 RoPE。</li></ul>',6))])}const f=l(h,[["render",_]]);export{B as __pageData,f as default};
